+        if (a[i] > a[i-1]) desc = false;
+        if (!asc && !desc) break;
+    }
+    if (asc) return;  // already sorted ascending
+    if (desc) {
+        // reverse the array to make it ascending
+        for (size_t i = 0; i < n / 2; ++i) {
+            std::swap(a[i], a[n - 1 - i]);
